import { useState, type FormEvent } from 'react';
import { JxButton, JxInput, JxSelect, JxSwitch } from '@jinx-ui/react';

export type ProfileSettingsValue = {
  name: string;
  language: 'ru' | 'en';
  emailNotifications: boolean;
};

type ProfileSettingsFormProps = {
  initialValue?: Partial<ProfileSettingsValue>;
  onSave: (settings: ProfileSettingsValue) => void;
};

const LANGUAGE_OPTIONS = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

export default function ProfileSettingsForm({ initialValue, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialValue?.name ?? '');
  const [language, setLanguage] = useState<'ru' | 'en'>(initialValue?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(
    initialValue?.emailNotifications ?? false,
  );

  const trimmedName = name.trim();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name: trimmedName, language, emailNotifications });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'grid', gap: 'var(--jx-space-4)', maxWidth: 'var(--jx-size-form)' }}
    >
      <JxInput
        label="Имя"
        value={name}
        onValueChange={setName}
        autoComplete="name"
        required
      />

      <JxSelect
        label="Язык интерфейса"
        value={language}
        onValueChange={(next: string) => setLanguage(next as 'ru' | 'en')}
        options={LANGUAGE_OPTIONS}
      />

      <JxSwitch
        label="Уведомления на почту"
        value={emailNotifications}
        onValueChange={setEmailNotifications}
      />

      <JxButton type="submit" variant="primary" disabled={trimmedName.length === 0}>
        Сохранить
      </JxButton>
    </form>
  );
}

